export type PartnerTier = 'featured' | 'standard';

export type Review = {
  author: string;
  rating: number;
  date: string;
  text: string;
};

export type Partner = {
  id: string;
  name: string;
  trade: string;
  phone: string;
  blurb: string;
  serviceArea: string;
  tier: PartnerTier;
  licensed: boolean;
  insured: boolean;
  yearsInBusiness?: number;
  rating?: number;
  reviewCount?: number;
  about?: string;
  // Service flags shown as badges on cards.
  freeEstimates?: boolean;
  open24Hours?: boolean;
  // Optional: Google Places ID for auto fetching hours and reviews at build time.
  // Look up at https://developers.google.com/maps/documentation/places/web-service/place-id
  googlePlaceId?: string;
  // Optional manual overrides. If set, win over anything Google returns.
  hours?: string[];
  reviews?: Review[];
};

